@page "/chat"
@using sv_e4e22c9d4d4d46d89931c9f64e488f2e.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(threadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea ChannelName="@selectedChannelName"
                 ChannelDescription="@selectedChannelDescription"
                 Messages="messages"
                 ThreadSummaries="threadSummaries"
                 IsLoadingMore="isLoadingMore"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage"
                 OnLoadMore="LoadMoreMessages" />

    @if (threadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<ThreadSummary> threadSummaries = [];
    private List<Message> threadReplies = [];
    private Message? threadRootMessage;

    private int? selectedChannelId;
    private string selectedChannelName = "";
    private string selectedChannelDescription = "";
    private bool threadOpen;
    private bool isLoadingMore;
    private int currentSkip;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        var channel = channels.First(c => c.Id == channelId);
        selectedChannelName = channel.Name;
        selectedChannelDescription = channel.Description;
        currentSkip = 0;
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        currentSkip = messages.Count;

        // Build thread summaries from messages that have replies
        threadSummaries = messages
            .Where(m => m.ReplyToId is null)
            .Select(m => new ThreadSummary(
                m.Id,
                messages.Count(r => r.ReplyToId == m.Id),
                messages.Where(r => r.ReplyToId == m.Id).Select(r => r.SentAt).DefaultIfEmpty(m.SentAt).Max()))
            .Where(t => t.ReplyCount > 0)
            .ToList();

        await ChatService.MarkChannelReadAsync(channelId);

        // Update local unread count
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = channel with { UnreadCount = 0 };
        }

        CloseThreadSync();
    }

    private async Task LoadMoreMessages()
    {
        if (selectedChannelId is null || isLoadingMore) return;
        isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(selectedChannelId.Value, currentSkip, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            currentSkip += older.Count;
        }
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannelId is null) return;
        var msg = await ChatService.SendMessageAsync(selectedChannelId.Value, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;
        threadReplies = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void CloseThreadSync()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private Task CloseThread()
    {
        CloseThreadSync();
        return Task.CompletedTask;
    }

    private async Task SendThreadReply(string content)
    {
        if (selectedChannelId is null || threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannelId.Value, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update thread summary
        var existing = threadSummaries.FindIndex(t => t.RootMessageId == threadRootMessage.Id);
        var summary = new ThreadSummary(threadRootMessage.Id, threadReplies.Count, reply.SentAt);
        if (existing >= 0)
            threadSummaries[existing] = summary;
        else
            threadSummaries.Add(summary);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Optimistically update the local message
        var idx = messages.FindIndex(m => m.Id == args.MessageId);
        if (idx >= 0)
        {
            var msg = messages[idx];
            var reactions = msg.Reactions.ToList();
            var existingReaction = reactions.FindIndex(r => r.Emoji == args.Emoji);
            if (existingReaction >= 0)
            {
                var r = reactions[existingReaction];
                reactions[existingReaction] = r with { Users = [..r.Users, "You"] };
            }
            else
            {
                reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
            messages[idx] = msg with { Reactions = reactions };
        }
    }
}

